def find_path(graph, start, goal):
    # Initialize the stack for DFS
    stack = [(start, [start])]
    visited = set()

    while stack:
        (node, path) = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for next_node in graph.get(node, []):
                if next_node not in visited:
                    stack.append((next_node, path + [next_node]))
    return None
